      SUBROUTINE TWIT2RCC     DETERMINES CONTRIBUTION OF SECOND-ORDER TRANSFER MATRIX ANDC     PARTIAL OF BEAM CENTROID TO PARTIAL OF FIRST-ORDER TRANSFERC     MATRIX USING OFF-AXIS EXPANSIONCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'COCOM.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'RS.CIN'      INCLUDE 'T.CIN'CC     CONTRIBUTION OF SECOND ORDER TO FIRSTC      DO 10 J = 1, 6      DO 10 K = 1, 6      RT(J,K) = 0.0   10 CONTINUEC      DO 20 J = 1, 5      IND = 0      DO 20 L2 = 1, 6      DO 20 L1 = 1, L2      IND = IND + 1      RT(J,L1) = RT(J,L1) + T(J,IND)*COV(L2,NV2)      RT(J,L2) = RT(J,L2) + T(J,IND)*COV(L1,NV2)   20 CONTINUEC      RETURN      END